// EmailJS script
    emailjs.init("LuBiljR76tuT5HXpP"); // Replace with your EmailJS public key

    const form = document.getElementById("appointment-form");
    const formSteps = document.querySelectorAll(".form-step");
    let currentStep = 0;

    // Set min and max date for the date picker input
    const dateInput = document.getElementById("appointment-date");
    const today = new Date();
    const maxDate = new Date();
    maxDate.setDate(today.getDate() + 30);

// Format dates to yyyy-mm-dd
const toDateInputValue = (date) => {
    return date.toISOString().split('T')[0];
};

dateInput.min = toDateInputValue(today);
dateInput.max = toDateInputValue(maxDate);

    function showStep(step) {
        formSteps.forEach((fs, i) => {
            fs.classList.toggle("active", i === step);
        });
    }

    document.querySelectorAll(".next-btn").forEach(btn => {
        btn.addEventListener("click", () => {
            if (validateStep(currentStep)) {
                currentStep++;
                showStep(currentStep);
            }
        });
    });

    document.querySelectorAll(".prev-btn").forEach(btn => {
        btn.addEventListener("click", () => {
            currentStep--;
            showStep(currentStep);
        });
    });

    function validateStep(step) {
        const inputs = formSteps[step].querySelectorAll("input, select, textarea");
        for (let input of inputs) {
            if (!input.checkValidity()) {
                input.reportValidity();
                return false;
            }
        }

        if (step === 2) {
            const dateInput = form.querySelector("input[name='date']");
            const selectedDate = new Date(dateInput.value);
            const today = new Date();
            const maxDate = new Date();
            maxDate.setDate(today.getDate() + 30);

            today.setHours(0, 0, 0, 0);
            selectedDate.setHours(0, 0, 0, 0);

            if (selectedDate < today || selectedDate > maxDate) {
                alert("Please select a date within the next 30 days and not in the past.");
                return false;
            }
        }

        return true;
    }

    form.addEventListener("submit", function (e) {
        e.preventDefault();

        // Get the current time
        const now = new Date();
        const formattedTime = now.toLocaleString();

        // Set it to hidden field
        document.getElementById("submission-time").value = formattedTime;

        emailjs.sendForm('service_v8yqbpo', 'template_6otf6k4', form)
            .then(() => {
                form.style.display = 'none';
                document.getElementById("success-message").style.display = "block";
            })
            .catch(err => {
                alert("Something went wrong! Try again.");
                console.error(err);
            });
    });
